import zlib

def oracle(request):
    pages = [bytearray(bytes.fromhex(h)) for h in request["pages"]]
    np = len(pages); plen_page = len(pages[0]) if np else 0
    cp = request["checkpoint"]
    data = bytes.fromhex(request["log"])
    n = len(data)
    off = 0
    last_seq = 0
    recs = []
    while n - off >= 13:
        pl = int.from_bytes(data[off:off+4], "little")
        if pl > 4096:
            break
        if n - off < 13 + pl + 4:
            break
        sq = int.from_bytes(data[off+4:off+8], "little")
        kd = data[off+8]
        tid = int.from_bytes(data[off+9:off+13], "little")
        pay = data[off+13:off+13+pl]
        crc = int.from_bytes(data[off+13+pl:off+17+pl], "little")
        if zlib.crc32(data[off:off+13+pl]) & 0xffffffff != crc:
            break
        if sq <= last_seq or sq == 0:
            break
        if kd not in (1, 2, 3, 4) or tid == 0:
            break
        good = True
        if kd in (1, 4):
            good = (pl == 0)
        elif kd == 2:
            if pl < 7:
                good = False
            else:
                pi = int.from_bytes(pay[0:2], "little")
                bo = int.from_bytes(pay[2:4], "little")
                bc = int.from_bytes(pay[4:6], "little")
                good = bc > 0 and pl == 6 + bc and pi < np and bo + bc <= plen_page
        else:
            good = (pl == 8)
        if not good:
            break
        recs.append((sq, kd, tid, pay))
        off += 17 + pl
        last_seq = sq
    state = {}
    for sq, kd, tid, pay in recs:
        if kd == 1:
            state[tid] = []
        elif kd == 2:
            if tid in state:
                state[tid].append(pay)
        elif kd == 3:
            if tid in state:
                inc = state.pop(tid)
                cnt = int.from_bytes(pay[0:4], "little")
                dg = int.from_bytes(pay[4:8], "little")
                if cnt == len(inc) and (zlib.crc32(b"".join(inc)) & 0xffffffff) == dg and sq > cp:
                    for p in inc:
                        pi = int.from_bytes(p[0:2], "little")
                        bo = int.from_bytes(p[2:4], "little")
                        bc = int.from_bytes(p[4:6], "little")
                        pages[pi][bo:bo+bc] = p[6:]
        else:
            state.pop(tid, None)
    return {"pages": [p.hex() for p in pages], "valid_bytes": off, "last_seq": last_seq}
